import {
  pgTable,
  text,
  timestamp,
  boolean,
  uuid,
  varchar,
  pgEnum,
  index,
  jsonb,
  type AnyPgColumn,
} from "drizzle-orm/pg-core"
import { relations } from "drizzle-orm"

// ─────────────────────────────────────────────────────────────────────────────
// BETTER AUTH TABLES (Generated by bunx auth generate)
// ─────────────────────────────────────────────────────────────────────────────

export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at")
    .defaultNow()
    .$onUpdate(() => new Date())
    .notNull(),
  username: text("username").unique(),
  displayUsername: text("display_username"),
  // Better Auth admin plugin fields
  role: text("role"),
  banned: boolean("banned").default(false),
  banReason: text("ban_reason"),
  banExpires: timestamp("ban_expires"),
  phone: text("phone"),
  // ─── Muvx custom admin fields ─────────────────────────────────────
  // Suspension is independent of ban: suspended users see an appeal
  // screen on login and can request reinstatement. Banning is permanent
  // (or until unbanned) and offers no appeal path.
  suspendedAt: timestamp("suspended_at"),
  suspendedUntil: timestamp("suspended_until"),
  suspendedReason: text("suspended_reason"),
  suspendedBy: text("suspended_by").references((): AnyPgColumn => user.id, {
    onDelete: "set null",
  }),
  // The latest appeal submitted by the user; cleared on lift/ban resolution.
  appealMessage: text("appeal_message"),
  appealSubmittedAt: timestamp("appeal_submitted_at"),
  // "open" | "approved" | "denied" — null when no appeal in flight
  // TODO phase-2: convert to appealStatusEnum once we move all enum
  // declarations to the top of the file (currently the enum would have
  // to be declared after this table, which breaks Drizzle's init order).
  appealStatus: text("appeal_status"),
  // Last admin who resolved the most recent appeal (set null on new appeal)
  appealResolvedBy: text("appeal_resolved_by").references(
    (): AnyPgColumn => user.id,
    { onDelete: "set null" }
  ),
})

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at").notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    activeOrganizationId: text("active_organization_id").references(
      () => organization.id,
      { onDelete: "set null" }
    ),
    impersonatedBy: text("impersonated_by"),
  },
  (table) => [index("session_userId_idx").on(table.userId)],
)

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at"),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at"),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("account_userId_idx").on(table.userId)],
)

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at")
      .defaultNow()
      .$onUpdate(() => new Date())
      .notNull(),
  },
  (table) => [index("verification_identifier_idx").on(table.identifier)],
)

export const organization = pgTable("organization", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  logo: text("logo"),
  createdAt: timestamp("created_at").notNull(),
  metadata: text("metadata"),
  // ─── Suspension (set by platform admin) ──────────────────────────────────
  // When suspended=true, all workspace members are blocked at the
  // (dashboard) layout level — they see a "workspace suspended" screen
  // with the reason. Platform admins (user.role='admin') always bypass.
  suspended: boolean("suspended").notNull().default(false),
  suspendedAt: timestamp("suspended_at"),
  suspendedReason: text("suspended_reason"),
  suspendedBy: text("suspended_by").references(() => user.id, {
    onDelete: "set null",
  }),

  // ─── Phase 3 — workspace profile (WS-09, WS-10, WS-14) ───────────────────
  // Operational / regulatory fields surfaced on /settings/workspace.
  // businessType controls dispatcher/ops defaults; dotNumber / mcNumber
  // are the FMCSA-issued identifiers for US carriers. currency + timeZone
  // + fiscalYearStart set the financial + scheduling defaults used by
  // later invoice/payroll modules.
  businessType: text("business_type"), // "broker" | "carrier" | "shipper" | "3pl" | "other"
  dotNumber: text("dot_number"),
  mcNumber: text("mc_number"),
  ein: text("ein"),
  phone: text("phone"),
  addressLine1: text("address_line1"),
  addressLine2: text("address_line2"),
  city: text("city"),
  state: text("state"),
  postalCode: text("postal_code"),
  country: text("country").default("US"),
  defaultCurrency: text("default_currency").notNull().default("USD"),
  timeZone: text("time_zone").notNull().default("America/Chicago"),
  fiscalYearStart: text("fiscal_year_start").notNull().default("01-01"), // MM-DD
})

export const member = pgTable(
  "member",
  {
    id: text("id").primaryKey(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    role: text("role").default("member").notNull(),
    createdAt: timestamp("created_at").notNull(),
    // ─── WS-26: workspace-scoped suspension ─────────────────────────
    // Independent of platform-level user.suspendedAt. A workspace
    // owner/admin can suspend a member from this workspace only;
    // their other workspace memberships and platform-level access are
    // untouched. When suspendedAt is set AND (suspendedUntil is null
    // OR suspendedUntil is in the future), the dashboard layout
    // blocks them on their next /dashboard request.
    suspendedAt: timestamp("suspended_at"),
    suspendedUntil: timestamp("suspended_until"),
    suspendedReason: text("suspended_reason"),
    suspendedBy: text("suspended_by").references(() => user.id, {
      onDelete: "set null",
    }),
  },
  (table) => [
    index("member_organizationId_idx").on(table.organizationId),
    index("member_userId_idx").on(table.userId),
    index("member_suspended_idx").on(
      table.organizationId,
      table.suspendedAt
    ),
  ],
)

export const invitation = pgTable(
  "invitation",
  {
    id: text("id").primaryKey(),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    email: text("email").notNull(),
    role: text("role"),
    status: text("status").default("pending").notNull(),
    expiresAt: timestamp("expires_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    // Nullable + SET NULL: when an inviter is hard-deleted their sent
    // invitations survive (audit trail). inviter_email below preserves
    // the address for forensic review.
    inviterId: text("inviter_id").references(() => user.id, {
      onDelete: "set null",
    }),
    inviterEmail: text("inviter_email"),
  },
  (table) => [
    index("invitation_organizationId_idx").on(table.organizationId),
    index("invitation_email_idx").on(table.email),
    index("invitation_status_idx").on(
      table.organizationId,
      table.status
    ),
  ],
)

// ─────────────────────────────────────────────────────────────────────────────
// DYNAMIC ACCESS CONTROL — organizationRole table (WS-31/32/33)
// Better Auth uses camelCase JS property names; the DB columns are
// snake_case. This table maps to the organization_role table created
// by drizzle migration 0011.
// ─────────────────────────────────────────────────────────────────────────────

export const organizationRole = pgTable(
  "organization_role",
  {
    id: text("id").primaryKey(), // BA requires this even though CRUD endpoints don't use it directly
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    role: text("role").notNull(),
    permission: text("permission").notNull(), // JSON stringified: { resource: ["action1", ...] }
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
  },
  (table) => [
    index("organization_role_organization_id_idx").on(table.organizationId),
    index("organization_role_role_idx").on(table.role),
    // Composite PK: (organizationId, role) is unique per workspace
    index("organization_role_pk_idx").on(table.organizationId, table.role),
  ],
)

// ─────────────────────────────────────────────────────────────────────────────
// AUTH RELATIONS
// ─────────────────────────────────────────────────────────────────────────────

export const userRelations = relations(user, ({ many }) => ({
  sessions: many(session),
  accounts: many(account),
  members: many(member),
  invitations: many(invitation),
}))

export const sessionRelations = relations(session, ({ one }) => ({
  user: one(user, {
    fields: [session.userId],
    references: [user.id],
  }),
}))

export const accountRelations = relations(account, ({ one }) => ({
  user: one(user, {
    fields: [account.userId],
    references: [user.id],
  }),
}))

export const organizationRelations = relations(organization, ({ many }) => ({
  members: many(member),
  invitations: many(invitation),
  // Dynamic Access Control — custom per-workspace roles (WS-31/32/33)
  organizationRoles: many(organizationRole),
  // TMS tables
  loads: many(load),
  drivers: many(driver),
  trucks: many(truck),
  trailers: many(trailer),
  invoices: many(invoice),
  trips: many(trip),
  carrierPayments: many(carrierPayment),
  apExpenses: many(apExpense),
  payStubs: many(payStub),
}))

export const memberRelations = relations(member, ({ one }) => ({
  organization: one(organization, {
    fields: [member.organizationId],
    references: [organization.id],
  }),
  user: one(user, {
    fields: [member.userId],
    references: [user.id],
  }),
}))

export const invitationRelations = relations(invitation, ({ one }) => ({
  organization: one(organization, {
    fields: [invitation.organizationId],
    references: [organization.id],
  }),
  inviter: one(user, {
    fields: [invitation.inviterId],
    references: [user.id],
  }),
}))

export const organizationRoleRelations = relations(organizationRole, ({ one }) => ({
  organization: one(organization, {
    fields: [organizationRole.organizationId],
    references: [organization.id],
  }),
}))

// ─────────────────────────────────────────────────────────────────────────────
// SYSTEM ERROR LOG
// ─────────────────────────────────────────────────────────────────────────────
//
// `error_log` — server-side errors and warnings, written by
// `lib/logger.ts`. Powers the System Health card on the admin
// overview. Keep this lean: a daily cron could prune rows older
// than 30 days; we'll add that when we have cron infra.
//

export const errorLog = pgTable(
  "error_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** "error" | "warn" | "info" */
    level: text("level").notNull().default("error"),
    /** Module / file that wrote the row. */
    source: text("source").notNull(),
    message: text("message").notNull(),
    /** Stack trace (if any). */
    stack: text("stack"),
    /** Free-form JSON metadata. */
    metadata: jsonb("metadata").$type<Record<string, unknown>>(),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [index("error_log_createdAt_idx").on(table.createdAt)]
)

// ─────────────────────────────────────────────────────────────────────────────
// COMMUNICATIONS
// ─────────────────────────────────────────────────────────────────────────────
//
// `announcement` — in-app banner shown to users.
//   - kind: "info" | "warn" | "success" | "maintenance"
//   - scope: "global" (all users) or "org" (one workspace) or "admins_only"
//   - dismissible: whether the user can hide it
//   - startsAt / endsAt: optional scheduling
//
// `email_broadcast` — a record of every broadcast email sent.
//   Stores subject, body, audience size, sent count, fail count, and
//   the Resend batch id (so we can correlate with their dashboard).
//
// `email_log` — every transactional email we sent (OTP, reset, etc.)
//   so admins can debug "did the user get the email?"
//

export const announcement = pgTable(
  "announcement",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    title: text("title").notNull(),
    body: text("body").notNull(),
    kind: text("kind").notNull().default("info"),
    /** "global" | "org" | "admins_only" */
    scope: text("scope").notNull().default("global"),
    /** When scope="org", the target workspace. */
    organizationId: text("organization_id").references(() => organization.id, {
      onDelete: "cascade",
    }),
    dismissible: boolean("dismissible").notNull().default(true),
    startsAt: timestamp("starts_at"),
    endsAt: timestamp("ends_at"),
    createdBy: text("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [
    index("announcement_scope_idx").on(table.scope, table.startsAt, table.endsAt),
  ]
)

export const emailBroadcast = pgTable(
  "email_broadcast",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    subject: text("subject").notNull(),
    body: text("body").notNull(),
    /** "all" | "active_30d" | "admins" | "org:<id>" */
    audience: text("audience").notNull(),
    /** Snapshot of the audience size at send time. */
    audienceSize: text("audience_size").notNull(),
    sentCount: text("sent_count").notNull().default("0"),
    failedCount: text("failed_count").notNull().default("0"),
    /** Resend batch id (optional). */
    batchId: text("batch_id"),
    // Nullable + SET NULL: when the sender (admin) is hard-deleted,
    // the broadcast record stays but loses the FK to preserve audit trail.
    sentBy: text("sent_by").references(() => user.id, { onDelete: "set null" }),
    sentAt: timestamp("sent_at").notNull().defaultNow(),
  },
  (table) => [
    index("email_broadcast_sentAt_idx").on(table.sentAt),
  ]
)

export const emailLog = pgTable(
  "email_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    to: text("to_email").notNull(),
    subject: text("subject").notNull(),
    /** "otp" | "broadcast" | "transactional" | "other" */
    kind: text("kind").notNull().default("transactional"),
    /** Resend message id */
    providerId: text("provider_id"),
    success: boolean("success").notNull(),
    error: text("error"),
    sentAt: timestamp("sent_at").notNull().defaultNow(),
  },
  (table) => [
    index("email_log_to_idx").on(table.to),
    index("email_log_sentAt_idx").on(table.sentAt),
  ]
)

// ─────────────────────────────────────────────────────────────────────────────
// FEATURE FLAGS
// ─────────────────────────────────────────────────────────────────────────────
//
// Three-tier feature-flag system.
//
//   feature_flag      — the definition (key, name, default value, rollout %)
//   user_feature_flag — per-user override (highest precedence)
//   org_feature_flag  — per-org override (medium precedence)
//
// Precedence when reading a flag for a (user, org) pair:
//   1. user_feature_flag (if row exists)
//   2. org_feature_flag  (if row exists and user is in that org)
//   3. rollout % bucket against user.id hash
//   4. feature_flag.default_value
//
// Rollout % uses a stable hash of (flag.key + user.id) so the same
// user always gets the same answer for the same flag.

export const featureFlag = pgTable("feature_flag", {
  key: text("key").primaryKey(),
  name: text("name").notNull(),
  description: text("description"),
  /** "boolean" | "string" | "number" */
  kind: text("kind").notNull().default("boolean"),
  /** Default value (stringified; the helper parses to kind). */
  defaultValue: text("default_value").notNull().default("false"),
  /** 0..100. When 0, only overrides apply. When 100, everyone gets default. */
  rolloutPercent: text("rollout_percent").notNull().default("0"),
  /** Admin who created/updated the flag. */
  updatedBy: text("updated_by").references(() => user.id, {
    onDelete: "set null",
  }),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
})

export const userFeatureFlag = pgTable(
  "user_feature_flag",
  {
    featureFlagKey: text("feature_flag_key")
      .notNull()
      .references(() => featureFlag.key, { onDelete: "cascade" }),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    value: text("value").notNull(),
    createdBy: text("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [
    index("user_feature_flag_user_idx").on(table.userId),
    index("user_feature_flag_key_idx").on(table.featureFlagKey),
  ]
)

export const orgFeatureFlag = pgTable(
  "org_feature_flag",
  {
    featureFlagKey: text("feature_flag_key")
      .notNull()
      .references(() => featureFlag.key, { onDelete: "cascade" }),
    organizationId: text("organization_id")
      .notNull()
      .references(() => organization.id, { onDelete: "cascade" }),
    value: text("value").notNull(),
    createdBy: text("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [
    index("org_feature_flag_org_idx").on(table.organizationId),
    index("org_feature_flag_key_idx").on(table.featureFlagKey),
  ]
)

// ─────────────────────────────────────────────────────────────────────────────
// SECURITY & ABUSE-MITIGATION TABLES
// ─────────────────────────────────────────────────────────────────────────────
//
// `email_allowlist` — only addresses matching one of these patterns can
//   sign up. Supports exact email or `*@example.com` wildcards. If the
//   list is non-empty, signup is gated by it.
//
// `email_blocklist` — addresses or domain wildcards that are always
//   rejected. Checked before allowlist.
//
// `ip_allowlist` — admin-source IP allowlist. Empty = allow all
//   (default). When populated, /admin/* requests must originate from
//   one of these CIDRs.
//
// `signup_attempt` — every signup attempt (success or fail) with the
//   IP, UA, and failure reason. Powers the brute-force dashboard.
//

export const emailAllowlist = pgTable(
  "email_allowlist",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** Either an exact email "user@x.com" or a domain wildcard "*@x.com". */
    pattern: text("pattern").notNull().unique(),
    reason: text("reason"),
    createdBy: text("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [index("email_allowlist_pattern_idx").on(table.pattern)]
)

export const emailBlocklist = pgTable(
  "email_blocklist",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    pattern: text("pattern").notNull().unique(),
    reason: text("reason"),
    createdBy: text("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [index("email_blocklist_pattern_idx").on(table.pattern)]
)

export const ipAllowlist = pgTable(
  "ip_allowlist",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    /** CIDR or single IP. e.g. "203.0.113.0/24" or "203.0.113.5". */
    cidr: text("cidr").notNull().unique(),
    label: text("label"),
    /** Null = never expires. */
    expiresAt: timestamp("expires_at"),
    createdBy: text("created_by").references(() => user.id, {
      onDelete: "set null",
    }),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [index("ip_allowlist_cidr_idx").on(table.cidr)]
)

export const signupAttempt = pgTable(
  "signup_attempt",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    email: text("email").notNull(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    /** True if signup was allowed to proceed (account created). */
    success: boolean("success").notNull(),
    /** On success: null. On failure: "blocked_email" | "blocked_ip" | "rate_limited" | "invalid_input" | … */
    reason: text("reason"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [
    index("signup_attempt_created_idx").on(table.createdAt),
    index("signup_attempt_ip_idx").on(table.ipAddress),
    index("signup_attempt_email_idx").on(table.email),
  ]
)

/**
 * System settings — singleton row, holds cross-cutting toggles
 * (maintenance mode, signup policy, default ban duration).
 * Pattern: most-recent row wins; we never delete old rows so we have
 * a history of who flipped which switch and when.
 */
export const systemSetting = pgTable("system_setting", {
  id: uuid("id").primaryKey().defaultRandom(),
  key: text("key").notNull(),
  value: jsonb("value").$type<unknown>(),
  updatedBy: text("updated_by").references(() => user.id, {
    onDelete: "set null",
  }),
  updatedAt: timestamp("updated_at")
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
})

// ─────────────────────────────────────────────────────────────────────────────
// AUDIT LOG
// ─────────────────────────────────────────────────────────────────────────────
//
// Append-only audit log. Every admin action (ban, suspend, set role,
// impersonate, delete user, delete org, …) writes one row.
//
// `hash` is SHA-256 of the previous row's hash + the current row's
// canonical payload — a tamper-evident chain. `prevHash` is stored
// explicitly so a verifier can walk the chain without a join.
//
// We do NOT add update/delete mutations in app code. The only writer
// is lib/audit.ts (server-side). If a row needs correcting, write a
// compensating "amendment" row that points at the original.
//

export const auditLog = pgTable(
  "audit_log",
  {
    id: uuid("id").primaryKey().defaultRandom(),
    // Nullable + SET NULL: when an admin is hard-deleted, their past
    // audit rows are preserved but lose the FK. The `actorEmail` column
    // keeps the email for forensic purposes (or "deleted-user-{id}" once
    // the cascade library anonymizes it).
    actorId: text("actor_id").references(() => user.id, {
      onDelete: "set null",
    }),
    actorEmail: text("actor_email").notNull(),
    // "user.ban" | "user.unban" | "user.suspend" | "user.lift-suspension" |
    // "user.set-role" | "user.reset-password" | "user.force-verify-email" |
    // "user.remove" | "user.impersonate" | "appeal.resolve" |
    // "org.delete" | "session.revoke" | "session.revoke-all" |
    // "system.maintenance" | "system.announcement" | …
    action: text("action").notNull(),
    // "user" | "org" | "appeal" | "session" | "system" | "billing"
    targetType: text("target_type").notNull(),
    targetId: text("target_id"),
    // Denormalized display label (email / org name / system message)
    targetLabel: text("target_label"),
    // Free-form context (reason, duration, payload, before/after diffs)
    metadata: jsonb("metadata").$type<Record<string, unknown>>(),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    // Hash chain — set in lib/audit.ts on insert
    prevHash: text("prev_hash"),
    hash: text("hash"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
  },
  (table) => [
    index("audit_log_createdAt_idx").on(table.createdAt),
    index("audit_log_actorId_idx").on(table.actorId),
    index("audit_log_action_idx").on(table.action),
    index("audit_log_target_idx").on(table.targetType, table.targetId),
  ]
)

// ─────────────────────────────────────────────────────────────────────────────
// TMS TABLES (Your business data - all with tenantId for multi-tenancy)
// ─────────────────────────────────────────────────────────────────────────────

// Enum for appeal status (Phase 1) — was freeform text, this enforces
// the documented status set so audit/inbox queries can't drift.
export const appealStatusEnum = pgEnum("appeal_status", [
  "open",
  "approved",
  "denied",
])

// Enum for appeal status (Phase 1, defined here for future use — not yet
// applied to user.appealStatus because Drizzle needs the enum declared
// before the table that uses it, and user is the very first table).
// export const appealStatusEnum = pgEnum("appeal_status", [
//   "open",
//   "approved",
//   "denied",
// ])

// Enum for load status
export const loadStatusEnum = pgEnum("load_status", [
  "available",
  "booked",
  "dispatched",
  "in_transit",
  "delivered",
  "completed",
  "cancelled",
])

// Loads table (freight/shipments)
export const load = pgTable("load", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  loadNumber: varchar("load_number", { length: 50 }).notNull(),
  status: loadStatusEnum("status").notNull().default("available"),

  // Customer info
  customerId: text("customer_id"),
  customerName: varchar("customer_name", { length: 255 }),
  customerEmail: varchar("customer_email", { length: 255 }),

  // Origin
  originAddress: text("origin_address"),
  originCity: varchar("origin_city", { length: 100 }),
  originState: varchar("origin_state", { length: 50 }),
  originZip: varchar("origin_zip", { length: 20 }),
  originContact: varchar("origin_contact", { length: 100 }),
  originPhone: varchar("origin_phone", { length: 50 }),
  originAppointment: timestamp("origin_appointment"),

  // Destination
  destAddress: text("dest_address"),
  destCity: varchar("dest_city", { length: 100 }),
  destState: varchar("dest_state", { length: 50 }),
  destZip: varchar("dest_zip", { length: 20 }),
  destContact: varchar("dest_contact", { length: 100 }),
  destPhone: varchar("dest_phone", { length: 50 }),
  destAppointment: timestamp("dest_appointment"),

  // Load details
  loadType: varchar("load_type", { length: 50 }), // van, reefer, flatbed
  commodity: varchar("commodity", { length: 255 }),
  weight: varchar("weight", { length: 50 }),
  rate: varchar("rate", { length: 50 }), // Revenue rate
  customerRate: varchar("customer_rate", { length: 50 }),
  carrierRate: varchar("carrier_rate", { length: 50 }),
  miles: varchar("miles", { length: 50 }),
  deadhead: varchar("deadhead", { length: 50 }),

  // Profit tracking
  targetProfit: varchar("target_profit", { length: 50 }),
  actualProfit: varchar("actual_profit", { length: 50 }),

  // BOL tracking
  bolNumber: varchar("bol_number", { length: 50 }),
  bolReceived: boolean("bol_received").default(false),
  podSigned: boolean("pod_signed").default(false),

  // Rate confirmation
  rateConfirmNumber: varchar("rate_confirm_number", { length: 50 }),
  rateConfirmed: boolean("rate_confirmed").default(false),

  // Pinned (sidebar quick-access)
  isStarred: boolean("is_starred").notNull().default(false),

  // Timestamps
  pickupDate: timestamp("pickup_date"),
  deliveryDate: timestamp("delivery_date"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Trips table (load runs)
export const trip = pgTable("trip", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  tripNumber: varchar("trip_number", { length: 50 }).notNull(),
  loadId: text("load_id").references(() => load.id),
  driverId: text("driver_id").references(() => driver.id),
  truckId: text("truck_id").references(() => truck.id),
  trailerId: text("trailer_id").references(() => trailer.id),
  status: varchar("status", { length: 50 }).notNull().default("pending"),
  startDate: timestamp("start_date"),
  endDate: timestamp("end_date"),
  totalMiles: varchar("total_miles", { length: 50 }),
  totalRevenue: varchar("total_revenue", { length: 50 }),
  totalExpense: varchar("total_expense", { length: 50 }),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Drivers table
export const driver = pgTable("driver", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  // SET NULL on user delete: the driver record stays (workspace-owned)
  // but the link to the user account is severed. PII (email, phone) is
  // wiped by `anonymizeDriverForUser` in `lib/cascade.ts`.
  userId: text("user_id").references(() => user.id, { onDelete: "set null" }),
  firstName: varchar("first_name", { length: 100 }).notNull(),
  lastName: varchar("last_name", { length: 100 }).notNull(),
  email: varchar("email", { length: 255 }),
  phone: varchar("phone", { length: 50 }),
  cdlNumber: varchar("cdl_number", { length: 50 }),
  cdlState: varchar("cdl_state", { length: 50 }),
  cdlExpiration: timestamp("cdl_expiration"),
  dateOfBirth: timestamp("date_of_birth"),
  address: text("address"),
  city: varchar("city", { length: 100 }),
  state: varchar("state", { length: 50 }),
  zip: varchar("zip", { length: 20 }),
  status: varchar("status", { length: 50 }).notNull().default("active"),
  hireDate: timestamp("hire_date"),
  payRate: varchar("pay_rate", { length: 50 }),
  payType: varchar("pay_type", { length: 50 }),
  emergencyContact: varchar("emergency_contact", { length: 100 }),
  emergencyPhone: varchar("emergency_phone", { length: 50 }),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Trucks table
export const truck = pgTable("truck", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  unitNumber: varchar("unit_number", { length: 50 }).notNull(),
  make: varchar("make", { length: 100 }),
  model: varchar("model", { length: 100 }),
  year: varchar("year", { length: 10 }),
  vin: varchar("vin", { length: 50 }),
  licensePlate: varchar("license_plate", { length: 50 }),
  licenseState: varchar("license_state", { length: 50 }),
  licenseExpiration: timestamp("license_expiration"),
  fuelType: varchar("fuel_type", { length: 50 }),
  fuelCapacity: varchar("fuel_capacity", { length: 50 }),
  status: varchar("status", { length: 50 }).notNull().default("available"),
  currentLocation: varchar("current_location", { length: 255 }),
  currentMiles: varchar("current_miles", { length: 50 }),
  nextServiceMiles: varchar("next_service_miles", { length: 50 }),
  nextServiceDate: timestamp("next_service_date"),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Trailers table
export const trailer = pgTable("trailer", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  unitNumber: varchar("unit_number", { length: 50 }).notNull(),
  type: varchar("type", { length: 50 }),
  make: varchar("make", { length: 100 }),
  model: varchar("model", { length: 100 }),
  year: varchar("year", { length: 10 }),
  vin: varchar("vin", { length: 50 }),
  licensePlate: varchar("license_plate", { length: 50 }),
  licenseState: varchar("license_state", { length: 50 }),
  licenseExpiration: timestamp("license_expiration"),
  status: varchar("status", { length: 50 }).notNull().default("available"),
  currentLocation: varchar("current_location", { length: 255 }),
  length: varchar("length", { length: 50 }),
  capacity: varchar("capacity", { length: 50 }),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Invoices table
export const invoice = pgTable("invoice", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  invoiceNumber: varchar("invoice_number", { length: 50 }).notNull(),
  loadId: text("load_id").references(() => load.id),
  customerId: text("customer_id"),
  customerName: varchar("customer_name", { length: 255 }),
  customerEmail: varchar("customer_email", { length: 255 }),
  amount: varchar("amount", { length: 50 }).notNull(),
  status: varchar("status", { length: 50 }).notNull().default("pending"),
  dueDate: timestamp("due_date"),
  paidDate: timestamp("paid_date"),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Carrier payments table
export const carrierPayment = pgTable("carrier_payment", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  tripId: text("trip_id").references(() => trip.id),
  driverId: text("driver_id").references(() => driver.id),
  amount: varchar("amount", { length: 50 }).notNull(),
  status: varchar("status", { length: 50 }).notNull().default("pending"),
  paymentDate: timestamp("payment_date"),
  paymentMethod: varchar("payment_method", { length: 50 }),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// AP Expenses table
export const apExpense = pgTable("ap_expense", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  tripId: text("trip_id").references(() => trip.id),
  driverId: text("driver_id").references(() => driver.id),
  type: varchar("type", { length: 100 }).notNull(),
  vendor: varchar("vendor", { length: 255 }),
  amount: varchar("amount", { length: 50 }).notNull(),
  date: timestamp("date").notNull(),
  status: varchar("status", { length: 50 }).notNull().default("pending"),
  notes: text("notes"),
  receipt: text("receipt"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Pay stubs table
export const payStub = pgTable("pay_stub", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  // SET NULL on driver delete: if a driver is removed, their pay stubs
  // survive (workspace-owned payroll records) but lose the FK pointer.
  driverId: text("driver_id")
    .notNull()
    .references(() => driver.id, { onDelete: "set null" }),
  payPeriodStart: timestamp("pay_period_start").notNull(),
  payPeriodEnd: timestamp("pay_period_end").notNull(),
  totalMiles: varchar("total_miles", { length: 50 }),
  payRate: varchar("pay_rate", { length: 50 }),
  grossPay: varchar("gross_pay", { length: 50 }).notNull(),
  deductions: varchar("deductions", { length: 50 }),
  netPay: varchar("net_pay", { length: 50 }).notNull(),
  status: varchar("status", { length: 50 }).notNull().default("pending"),
  paidDate: timestamp("paid_date"),
  notes: text("notes"),
  createdAt: timestamp("created_at").notNull().defaultNow(),
  updatedAt: timestamp("updated_at").notNull().defaultNow(),
})

// Pay items table (line items for pay stubs)
export const payItem = pgTable("pay_item", {
  id: text("id").primaryKey(),
  tenantId: text("tenant_id")
    .notNull()
    .references(() => organization.id, { onDelete: "cascade" }),
  // CASCADE on pay_stub delete: line items follow the parent stub.
  payStubId: text("pay_stub_id")
    .notNull()
    .references(() => payStub.id, { onDelete: "cascade" }),
  tripId: text("trip_id").references(() => trip.id),
  type: varchar("type", { length: 100 }).notNull(),
  description: varchar("description", { length: 255 }),
  quantity: varchar("quantity", { length: 50 }),
  rate: varchar("rate", { length: 50 }),
  amount: varchar("amount", { length: 50 }).notNull(),
  createdAt: timestamp("created_at").notNull().defaultNow(),
})

// ─────────────────────────────────────────────────────────────────────────────
// TMS RELATIONS
// ─────────────────────────────────────────────────────────────────────────────

export const loadRelations = relations(load, ({ one, many }) => ({
  organization: one(organization, {
    fields: [load.tenantId],
    references: [organization.id],
  }),
  trips: many(trip),
  invoices: many(invoice),
}))

export const tripRelations = relations(trip, ({ one, many }) => ({
  organization: one(organization, {
    fields: [trip.tenantId],
    references: [organization.id],
  }),
  load: one(load, {
    fields: [trip.loadId],
    references: [load.id],
  }),
  driver: one(driver, {
    fields: [trip.driverId],
    references: [driver.id],
  }),
  truck: one(truck, {
    fields: [trip.truckId],
    references: [truck.id],
  }),
  trailer: one(trailer, {
    fields: [trip.trailerId],
    references: [trailer.id],
  }),
  payItems: many(payItem),
  apExpenses: many(apExpense),
  carrierPayments: many(carrierPayment),
}))

export const driverRelations = relations(driver, ({ one, many }) => ({
  organization: one(organization, {
    fields: [driver.tenantId],
    references: [organization.id],
  }),
  user: one(user, {
    fields: [driver.userId],
    references: [user.id],
  }),
  trips: many(trip),
  payStubs: many(payStub),
  apExpenses: many(apExpense),
  carrierPayments: many(carrierPayment),
}))

export const truckRelations = relations(truck, ({ one, many }) => ({
  organization: one(organization, {
    fields: [truck.tenantId],
    references: [organization.id],
  }),
  trips: many(trip),
}))

export const trailerRelations = relations(trailer, ({ one, many }) => ({
  organization: one(organization, {
    fields: [trailer.tenantId],
    references: [organization.id],
  }),
  trips: many(trip),
}))

export const invoiceRelations = relations(invoice, ({ one }) => ({
  organization: one(organization, {
    fields: [invoice.tenantId],
    references: [organization.id],
  }),
  load: one(load, {
    fields: [invoice.loadId],
    references: [load.id],
  }),
}))

export const payStubRelations = relations(payStub, ({ one, many }) => ({
  organization: one(organization, {
    fields: [payStub.tenantId],
    references: [organization.id],
  }),
  driver: one(driver, {
    fields: [payStub.driverId],
    references: [driver.id],
  }),
  items: many(payItem),
}))

export const payItemRelations = relations(payItem, ({ one }) => ({
  organization: one(organization, {
    fields: [payItem.tenantId],
    references: [organization.id],
  }),
  payStub: one(payStub, {
    fields: [payItem.payStubId],
    references: [payStub.id],
  }),
  trip: one(trip, {
    fields: [payItem.tripId],
    references: [trip.id],
  }),
}))

export const carrierPaymentRelations = relations(carrierPayment, ({ one }) => ({
  organization: one(organization, {
    fields: [carrierPayment.tenantId],
    references: [organization.id],
  }),
  trip: one(trip, {
    fields: [carrierPayment.tripId],
    references: [trip.id],
  }),
  driver: one(driver, {
    fields: [carrierPayment.driverId],
    references: [driver.id],
  }),
}))

export const apExpenseRelations = relations(apExpense, ({ one }) => ({
  organization: one(organization, {
    fields: [apExpense.tenantId],
    references: [organization.id],
  }),
  trip: one(trip, {
    fields: [apExpense.tripId],
    references: [trip.id],
  }),
  driver: one(driver, {
    fields: [apExpense.driverId],
    references: [driver.id],
  }),
}))
